# Create additional Docker configuration files
nginx_config = '''events {
    worker_connections 1024;
}

http {
    upstream oasis_api {
        server oasis-api:8000;
    }

    # Rate limiting
    limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;

    # SSL configuration
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    server {
        listen 80;
        server_name localhost;

        # Redirect HTTP to HTTPS
        return 301 https://$server_name$request_uri;
    }

    server {
        listen 443 ssl;
        server_name localhost;

        ssl_certificate /etc/nginx/ssl/cert.pem;
        ssl_certificate_key /etc/nginx/ssl/key.pem;

        # API routes
        location /api/ {
            limit_req zone=api burst=20 nodelay;
            proxy_pass http://oasis_api;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
        }

        # Health check
        location /health {
            proxy_pass http://oasis_api/health;
        }

        # Documentation
        location /docs {
            proxy_pass http://oasis_api/docs;
        }
    }
}
'''

prometheus_config = '''global:
  scrape_interval: 15s
  evaluation_interval: 15s

rule_files:
  # - "first_rules.yml"
  # - "second_rules.yml"

scrape_configs:
  - job_name: 'oasis-api'
    static_configs:
      - targets: ['oasis-api:8000']
    metrics_path: '/metrics'
    scrape_interval: 30s

  - job_name: 'redis'
    static_configs:
      - targets: ['redis:6379']

  - job_name: 'prometheus'
    static_configs:
      - targets: ['localhost:9090']
'''

# Write Docker configuration files
with open(f"{base_dir}/docker/nginx.conf", "w", encoding="utf-8") as f:
    f.write(nginx_config)

with open(f"{base_dir}/docker/prometheus.yml", "w", encoding="utf-8") as f:
    f.write(prometheus_config)

# Create .dockerignore file
dockerignore_content = '''# Git
.git
.gitignore

# Documentation
*.md
docs/

# Development files
.env
.vscode/
.idea/

# Testing
tests/
coverage/
.coverage
.pytest_cache/

# Python
__pycache__/
*.pyc
*.pyo
*.pyd
.Python
*.so
.tox/
.coverage
.coverage.*
.cache
.pytest_cache/

# Virtual environments
venv/
env/
ENV/

# OS
.DS_Store
Thumbs.db

# Logs
logs/
*.log

# Temporary files
tmp/
temp/

# Node modules (if any)
node_modules/
npm-debug.log*
'''

with open(f"{base_dir}/.dockerignore", "w", encoding="utf-8") as f:
    f.write(dockerignore_content)

print("✅ Created Docker configuration files")
print("🎯 Files: nginx.conf, prometheus.yml, .dockerignore")
